    @GameTest(template="empty") public static void baseOreNeverSubstitutesDifferentMetalOrForeignNbt(GameTestHelper h){run(h,f->{f.credit(5);var named=new ItemStack(Items.GOLD_INGOT,4);named.getOrCreateTag().putInt("physical",1);var foreign=new ItemStack(Items.GOLD_INGOT,5);foreign.getOrCreateTag().putInt("physical",2);f.input.setItem(0,named);f.input.setItem(1,foreign);f.input.setItem(2,new ItemStack(Items.IRON_INGOT,5));f.operation();h.assertTrue(f.input.countItem(Items.GOLD_INGOT)==9&&f.input.countItem(Items.IRON_INGOT)==5&&f.output.isEmpty()&&f.tile.power()==5,"BASEORE ignoredcandidateNBT or merged broadingotstag");});}
    @GameTest(template="empty") public static void originalBaseOrePrimeNbtDoesNotExcludePlainOreEntryCandidates(GameTestHelper h){run(h,f->{f.credit(5);var prime=new ItemStack(Items.GOLD_INGOT,4);prime.getOrCreateTag().putInt("physical",1);f.input.setItem(0,prime);f.input.setItem(1,new ItemStack(Items.GOLD_INGOT,5));f.operation();h.assertTrue(f.input.isEmpty()&&f.result(Items.GOLD_BLOCK)==1&&f.tile.power()==4,"Original prime-vs-ore-entry NBTasymmetry changed");});}
    @GameTest(template="empty") public static void candidateOrderSkipsJunkAndPaysFirstNativeCraftableStack(GameTestHelper h){run(h,f->{f.credit(5);f.input.setItem(0,new ItemStack(Items.DIAMOND,2));f.input.setItem(1,new ItemStack(Items.GOLD_INGOT,9));f.input.setItem(2,new ItemStack(Items.IRON_INGOT,9));f.operation();h.assertTrue(f.result(Items.GOLD_BLOCK)==1&&f.result(Items.IRON_BLOCK)==0&&f.input.countItem(Items.DIAMOND)==2&&f.input.countItem(Items.IRON_INGOT)==9,"Original slotorder/onecraftbreak changed");});}
    @GameTest(template="empty") public static void fullOutputCannotConsumeInputOrOneVisCredit(GameTestHelper h){run(h,f->{f.credit(5);f.put(Items.GOLD_INGOT,9);for(int i=0;i<27;i++)f.output.setItem(i,new ItemStack(Items.DIAMOND,64));f.operation();h.assertTrue(f.input.countItem(Items.GOLD_INGOT)==9&&f.tile.power()==5&&f.tile.pendingOutputCount()==0,"Full output paidwithoutcapacity");});}
    @GameTest(template="empty") public static void remainingItemsAndResultReserveOutputCapacityTogether(GameTestHelper h){run(h,f->{f.mode(1);f.credit(5);f.put(Items.MILK_BUCKET,1);for(int i=0;i<26;i++)f.output.setItem(i,new ItemStack(Items.DIAMOND,64));f.withRecipe(special(1,Items.MILK_BUCKET,new ItemStack(Items.GOLD_INGOT),new ItemStack(Items.BUCKET),null,null,null),()->{f.operation();h.assertTrue(f.input.countItem(Items.MILK_BUCKET)==1&&f.tile.power()==5&&f.result(Items.GOLD_INGOT)==0,"Independentoutputsimulations overbooked oneslot");});});}
