    @GameTest(template="empty") public static void realDoubleChestProvidesBothHalvesThroughNativeCombinedContainer(GameTestHelper h){run(h,f->{
        BlockPos first=f.pos.above(),other=first.east();f.states.putIfAbsent(other.immutable(),f.level.getBlockState(other));
        var p=new net.minecraftforge.common.util.FakePlayer(f.level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"pattern_chest"));
        p.setPos(other.getX()+.5,other.getY(),other.getZ()+3.5);p.setYRot(0);
        var physicalChest=new ItemStack(Items.CHEST);p.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,physicalChest);
        var context=new net.minecraft.world.item.context.BlockPlaceContext(new net.minecraft.world.item.context.UseOnContext(p,net.minecraft.world.InteractionHand.MAIN_HAND,
                new net.minecraft.world.phys.BlockHitResult(first.getCenter().add(.5,0,0),Direction.EAST,first,false)));
        h.assertTrue(context.getClickedPos().equals(other)&&((BlockItem)Items.CHEST).place(context).consumesAction()&&physicalChest.isEmpty(),
                "Actual native second ChestBlockItem placement did not pay its fixture item");
        f.input=(ChestBlockEntity)f.level.getBlockEntity(first);var second=(ChestBlockEntity)f.level.getBlockEntity(other);
        var firstState=f.level.getBlockState(first);var secondState=f.level.getBlockState(other);
        var combined=ChestBlock.getContainer((ChestBlock)Blocks.CHEST,firstState,f.level,first,true);
        h.assertTrue(firstState.getValue(ChestBlock.TYPE)!=net.minecraft.world.level.block.state.properties.ChestType.SINGLE
                &&secondState.getValue(ChestBlock.TYPE)!=net.minecraft.world.level.block.state.properties.ChestType.SINGLE
                &&firstState.getValue(ChestBlock.TYPE)!=secondState.getValue(ChestBlock.TYPE)
                &&firstState.getValue(ChestBlock.FACING)==secondState.getValue(ChestBlock.FACING)
                &&combined!=null&&combined.getContainerSize()==54,"Native fixture chests did not join into an actual54slot container");
        f.input.setItem(0,new ItemStack(Items.GOLD_INGOT,4));second.setItem(0,new ItemStack(Items.GOLD_INGOT,5));f.credit(5);f.operation();
        h.assertTrue(f.input.isEmpty()&&second.isEmpty()&&f.result(Items.GOLD_BLOCK)==1&&f.tile.power()==4&&f.tile.pendingOutputCount()==0,
                "Combined native chest omitted a physical half or changed exact9gold/onecredit/oneblock payment");
    });}
