    @GameTest(template="empty") public static void remainderCallbackRemovingCrafterCannotLeaveFreeOutput(GameTestHelper h){run(h,f->{f.mode(1);f.credit(5);f.put(Items.GOLD_BLOCK,1);f.withRecipe(special(1,Items.GOLD_BLOCK,new ItemStack(Items.GOLD_INGOT,9),ItemStack.EMPTY,null,null,grid->f.block(f.pos,Blocks.DIAMOND_BLOCK.defaultBlockState())),()->{f.operation();h.assertTrue(f.input.countItem(Items.GOLD_BLOCK)==1&&f.output.isEmpty()&&f.tile.pendingOutputCount()==0&&f.level.getBlockState(f.pos).is(Blocks.DIAMOND_BLOCK),"Remainder callback paid detachedcrafter or restoredforeignblock");});});}
    @GameTest(template="empty") public static void sourceOnlyMigrationInstallsMissingNativeAndPreservesPaidTile(GameTestHelper h){run(h,f->{var paid=f.tile;f.credit(3.5f);var chunk=f.level.getChunkAt(f.pos);LegacyPatternCrafterMigration.repair(f.level,chunk);h.assertTrue(f.level.getBlockEntity(f.pos)==paid&&paid.power()==3.5f,"Migration erasedpaidnativeowner");f.level.removeBlockEntity(f.pos);LegacyPatternCrafterMigration.repair(f.level,chunk);h.assertTrue(f.level.getBlockEntity(f.pos) instanceof PatternCrafterBlockEntity&&f.level.getBlockEntity(f.pos)!=paid,"Storedcatalogueblockpalette didnotmigratenative");});}
    @GameTest(template="empty",timeoutTicks=260) public static void actualNativeWorldTicksPerformThreePulsesWithNoForcedCounter(GameTestHelper h){var f=new Fixture(h,302);f.credit(5);f.put(Items.GOLD_INGOT,36);h.runAfterDelay(65,()->{try{h.assertTrue(f.result(Items.GOLD_BLOCK)>=3&&f.result(Items.GOLD_BLOCK)<=4&&f.input.countItem(Items.GOLD_INGOT)==36-f.result(Items.GOLD_BLOCK)*9&&f.tile.power()==5-f.result(Items.GOLD_BLOCK),"Actualnativeblockticker skippedcadence or physicalpayment");}finally{f.close();}h.succeed();});}
